export function EquipmentGrid(e,n){const i="All"===n?e:e.filter(e=>e.category===n);if(0===i.length)return'<div class="no-results">No equipment found for this category.</div>';const t=[...new Set(e.map(e=>e.category))].sort().map(e=>`\n        <button class="equip-filter-btn ${n===e?"active":""}" data-filter="${e}">${e}</button>\n    `).join(""),a=i.map(e=>`\n        <div class="equipment-card" data-category="${e.category}">\n            <div class="equip-card-top">\n                <span class="equip-category-badge" data-service="${e.service}">${e.category}</span>\n                <span class="equip-service">${e.service}</span>\n            </div>\n            <h4 class="equip-name">${e.name}</h4>\n            <p class="equip-type">${e.type}</p>\n            <p class="equip-origin">Origin: ${e.origin}</p>\n            <p class="equip-description">${e.description}</p>\n        </div>\n    `).join("");return`\n        <div class="equipment-filter-bar">\n            <button class="equip-filter-btn ${"All"===n?"active":""}" data-filter="All">All</button>\n            ${t}\n        </div>\n        <div class="equipment-grid">\n            ${a}\n        </div>\n    `}